29	// 再接受总量 10、限价 20 的买单 bid（现金占用 200，可用 700）。
30	// 返回引擎与该买单编号；除显式说明外调用前保护尚未触线。
31	func riskTradeSetup(t *testing.T, lossLimit int64) (e *Engine, bid int64) {
32		t.Helper()
33		e, _ = NewEngine(1000)
34		mustSetMax(t, e, "A", 100)
35		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
36		first := mustBuy(t, e, "A", 10, 10)
37		if _, err := e.Fill(Trade{TradeID: 1, OrderID: first, Symbol: "A", Side: Buy, Price: 10, Qty: 10}); err != nil {
38			t.Fatal(err)
39		}
40		if err := e.StartTradingDay(1, lossLimit); err != nil {
41			t.Fatal(err)
42		}
43		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 5}, 1) // 净值 950，亏损 50
44		if e.RiskStatus().Baseline != 1000 || e.RiskStatus().Equity != 950 ||
45			e.RiskStatus().Loss != 50 || e.RiskStatus().Restricted {
46			t.Fatalf("开日与降价后的前置风险状态错误: %+v", e.RiskStatus())
47		}
48		bid = mustBuy(t, e, "A", 10, 20)
49		if e.Cash() != 900 || e.ReservedCash() != 200 || e.AvailableCash() != 700 || e.Position("A") != 10 {
