56	// TestRiskPartialBuyFillSettlesThenCancelsRemainder 覆盖主场景：部分买入成交先
57	// 成功入账，再由同一笔成交触发日内亏损保护、撤销剩余 6 股。逐笔核对资金、持仓、
58	// 成交结果、订单查询与全部新增记录。
59	func TestRiskPartialBuyFillSettlesThenCancelsRemainder(t *testing.T) {
